/**
 * The `dokka` adapter: Kotlin API references generated by Dokka. The symbol index is
 * `scripts/pages.json`, the file behind the site's own search box; pages are server-rendered
 * HTML. Dokka mangles names in paths (`ArcGISMap` becomes `-arc-g-i-s-map`), so a page URL is
 * always taken from the index, never built.
 */
import type { BoundSource, SourceAdapter } from '../../core/ports.js';
import type { CatalogRecord } from '../../core/types.js';
import {
  assertLive,
  indexRequest,
  isIndexCanary,
  oneLine,
  probeSource,
  readHtmlPage,
  siteIndexEnabled,
  symbolRecord,
  symbolTarget,
  unusableIndex,
} from '../kit/index.js';

/** One entry of `pages.json`: `name` is the declaration, `description` the qualified name. */
interface DokkaEntry {
  name?: unknown;
  description?: unknown;
  location?: unknown;
}

/** The declaration keyword of a Kotlin signature, after any modifiers and annotations. */
const DECLARATION =
  /(?:^|\s)(enum class|annotation class|fun interface|enum|class|interface|object|typealias|fun|val|var|constructor)\b/;

const KINDS: Readonly<Record<string, string>> = {
  'enum class': 'enum',
  enum: 'enum',
  'annotation class': 'annotation',
  'fun interface': 'interface',
  class: 'class',
  interface: 'interface',
  object: 'object',
  typealias: 'typealias',
  val: 'property',
  var: 'property',
  constructor: 'constructor',
};

/** Kinds that own members, so that their qualified name can be a `parent`. */
const OWNERS: ReadonlySet<string> = new Set(['class', 'interface', 'object', 'enum', 'annotation']);

interface Declaration {
  ref: string;
  qualified: string;
  signature: string;
  /** Undefined for `fun`, whose kind depends on the owner, and for entries without a keyword. */
  kind: string | undefined;
  keyword: string | undefined;
}

function declarations(src: BoundSource, entries: readonly unknown[]): Declaration[] {
  const base = src.url();
  const seen = new Set<string>();
  const found: Declaration[] = [];
  for (const entry of entries as ReadonlyArray<DokkaEntry | null>) {
    const { name, description, location } = entry ?? {};
    if (typeof description !== 'string' || typeof location !== 'string') continue;
    if (description === '' || location === '') continue;
    const ref = new URL(location, base).href;
    // Overloads share one page; the first declaration stands for it.
    if (!ref.startsWith(base) || seen.has(ref)) continue;
    seen.add(ref);
    const signature = typeof name === 'string' ? name : description;
    const keyword = DECLARATION.exec(signature.replace(/@\w+(?:\([^)]*\))?\s*/g, ''))?.[1];
    found.push({
      ref,
      qualified: description,
      signature,
      keyword,
      kind: keyword === undefined ? undefined : KINDS[keyword],
    });
  }
  return found;
}

/**
 * Catalogue records of a Dokka `pages.json`. An entry is a member when the name before its
 * last segment is a type of the same index; nested types are members of their outer type.
 * Titles drop the package (`Request.Builder.addHeader`), which goes to the breadcrumb.
 */
export function dokkaRecords(src: BoundSource, entries: readonly unknown[]): CatalogRecord[] {
  const all = declarations(src, entries);
  const types = new Set(
    all.filter((item) => item.kind !== undefined && OWNERS.has(item.kind)).map((d) => d.qualified),
  );
  return all.map((item) => {
    const parts = item.qualified.split('.');
    let start = parts.length - 1;
    while (start > 0 && types.has(parts.slice(0, start).join('.'))) start -= 1;
    const owned = start < parts.length - 1;
    const parent = owned ? parts.slice(0, -1).join('.') : undefined;
    const fallback = item.keyword === 'fun' ? (owned ? 'method' : 'function') : 'enum-entry';
    return symbolRecord(src, item.ref, parts.slice(start).join('.'), {
      symbol: parts.at(-1),
      qualified: item.qualified,
      symbolKind: item.kind ?? (item.keyword === undefined && !owned ? 'symbol' : fallback),
      parent,
      breadcrumb: start === 0 ? [] : [parts.slice(0, start).join('.'), ...parts.slice(start, -1)],
      description: oneLine(item.signature),
      ...(item.signature.includes('@Deprecated') ? { deprecated: true } : {}),
    });
  });
}

/**
 * `dokka`: one request for `scripts/pages.json` lists every type and member with its page;
 * each page is read as HTML through the Dokka profile.
 */
export const dokkaAdapter: SourceAdapter<'dokka'> = {
  type: 'dokka',
  maxEnumerateRequests: 1,

  async enumerate(ctx, src) {
    const url = src.url('scripts/pages.json');
    assertLive(src, url);
    if (!siteIndexEnabled(ctx, src)) return [];
    const { data } = await ctx.http.getJson(indexRequest(src, url, 'json'));
    if (!Array.isArray(data)) throw unusableIndex(url, 'The index is not a list of pages');
    const records = dokkaRecords(src, data);
    if (records.length === 0) {
      throw unusableIndex(url, 'No entry of the index has a description and a location');
    }
    return records;
  },

  read: (ctx, src, target) => readHtmlPage(ctx, src, target, { family: 'dokka' }),
  symbol: (ctx, src, record, detail) =>
    readHtmlPage(ctx, src, symbolTarget(record, detail), { family: 'dokka' }),
  probe: (ctx, src) => probeSource(ctx, src, { siteIndex: isIndexCanary(src) }),
};
